// ============================================================
// Nó: Atualizar histórico do lead com base no fluxo concluído
// ============================================================
const input = $input.first().json;
const historico = input.historico || [];

// Dados disponíveis no fluxo (certifique-se de que estão no payload)
const briefingType = $('Normalize Data').first().json['briefing-type'] || 'Briefing';
const leadName = $('Normalize Data').first().json['nome-completo'] || 'Lead';
const emailSent = $('Send email').first().json.message ? true : false;   // booleano
const planGenerated = $('Brief2Plan').first().json.output ? true : false;

// ============================================================
// 1. Mensagem de recebimento e tipo de briefing
// ============================================================
historico.push(
  `📥 Briefing do tipo "${briefingType}" recebido e processado com sucesso.`
);

// ============================================================
// 2. Mensagem sobre a geração do plano
// ============================================================
if (planGenerated) {
  historico.push(
    `📋 Plano de ação gerado automaticamente pelo agente Brief2Plan com base nas necessidades do lead.`
  );
} else {
  historico.push(
    `⚠️ Plano de ação não gerado (falha no agente). Verificar logs.`
  );
}

// ============================================================
// 3. Mensagem sobre o envio do e-mail
// ============================================================
if (emailSent) {
  historico.push(
    `📧 E-mail com o plano detalhado enviado para ${leadName} (${input.email || 'e-mail não informado'}).`
  );
} else {
  historico.push(
    `⏳ E-mail com o plano não enviado (falha na entrega). Retentativa agendada.`
  );
}

// ============================================================
// 4. Mensagem final de status (próximos passos)
// ============================================================
historico.push(
  `🔄 Lead aguarda retorno ou próxima interação. O time de vendas/técnico será notificado.`
);

// ============================================================
// Saída: atualizar o objeto com o novo histórico
// ============================================================
$input.first().json.historico = historico;

// (Opcional) Replicar para outros nós que dependam desse objeto
return $input.first().json;




